  "Toca para seguir": "Tocca per continuare",
  "por": "di",
  "La GTS es un banco online de futbolistas: dejas una copia repetida pidiendo otro futbolista a cambio, y cualquiera que tenga el que pides puede cambiártelo aunque no estés conectado.": "La GTS è una banca online di giocatori: lasci una copia doppia chiedendo un altro giocatore in cambio, e chiunque abbia quello che chiedi può scambiarlo anche se non sei connesso.",
  "Para usarla tienes que entrar con tu cuenta.": "Per usarla devi accedere con il tuo account.",
  "Ir a Perfil para entrar": "Vai al Profilo per accedere",
  "Recuperar": "Recupera",
  "Dejar un futbolista": "Lascia un giocatore",
  "Solo copias repetidas": "Solo copie doppie",
  "Mejora la «Ventanilla GTS» en Mejoras": "Migliora lo «Sportello GTS» in Potenziamenti",
  "Huecos: {openLength}/{slots}. La copia que dejas va sin entrenamiento, estrellas ni ascensión: tu futbolista se queda con todo. Un HÉROE ascendido sí puede dejar sus copias repetidas. No se pueden dejar Leyenda ni futbolistas de evento, ni repetir un cambio.": "Posti: {openLength}/{slots}. La copia che lasci va senza allenamento, stelle né ascensione: il tuo giocatore tiene tutto. Un EROE asceso può lasciare le sue copie doppie. Non si possono lasciare Leggende né giocatori evento, né ripetere uno scambio.",
  "Buscar futbolista (el que quieres o el que piden)": "Cerca giocatore (quello che vuoi o quello richiesto)",
  "Solo los que puedo cambiar": "Solo quelli che posso scambiare",
  "↻ Actualizar": "↻ Aggiorna",
  "{username} deja": "{username} lascia",
  "Estación Global de Intercambio": "Stazione Globale di Scambio",
  "Deja una copia repetida, pide el futbolista que te falta y recoge tu cambio cuando vuelvas.": "Lascia una copia doppia, chiedi il giocatore che ti manca e ritira il tuo scambio quando torni.",
  "Ese depósito ya no está: puede que alguien te lo acabe de cambiar.": "Quel deposito non c'è più: forse qualcuno l'ha appena scambiato.",
  "No se pudo cargar la GTS.": "Impossibile caricare la GTS.",
