  "Cada bug que reportes y se corrija te da 100 fichas. Repórtalos desde el 🐞 del menú o en Ajustes.": "Ogni bug che segnali e viene corretto ti dà 100 gettoni. Segnalali dal 🐞 del menu o in Impostazioni.",
