  "Necesitas conexión para reclamar el pase (hora del servidor).": "Ti serve una connessione per riscuotere il pass (ora del server).",
  "Cuenta online": "Account online",
  "El servicio online no está activado en esta versión. Tu progreso se guarda en este navegador (Ajustes » Exportar/Importar para llevarlo a otro). Con el servicio activo podrás entrar con Google, reservar tu nombre en todo el mundo, aparecer en el ranking global y guardar en la nube.": "Il servizio online non è attivo in questa versione. I tuoi progressi sono salvati in questo browser (Impostazioni » Esporta/Importa per portarli altrove). Con il servizio attivo potrai accedere con Google, prenotare il tuo nome in tutto il mondo, apparire nella classifica globale e salvare nel cloud.",
  "Estás jugando como invitado: tu progreso se guarda solo en este navegador. Entra con Google para reservar tu nombre en todo el mundo, aparecer en el ranking y guardar en la nube. Tu correo es privado: nunca aparece en el ranking.": "Stai giocando come ospite: i tuoi progressi sono salvati solo in questo browser. Accedi con Google per prenotare il tuo nome in tutto il mondo, apparire in classifica e salvare nel cloud. La tua email è privata: non appare mai in classifica.",
  "Nombre global: <b>{onlineName}</b> (permanente)": "Nome mondiale: <b>{onlineName}</b> (permanente)",
  "Reserva tu nombre global. Si «{profileName}» ya está ocupado, elige otro: tu progreso no se toca.": "Prenota il tuo nome mondiale. Se «{profileName}» è già preso, scegline un altro: i tuoi progressi non vengono toccati.",
