  "Las llaves y los niveles son de esta temporada: cuando termine, empieza una nueva con su propio pase. La EXP cuenta aunque no tengas llave: al abrir una fila puedes reclamar todo lo que ya hayas alcanzado.": "Le chiavi e i livelli sono di questa stagione: quando finisce, ne inizia una nuova con il suo pass. L'EXP conta anche senza chiave: aprendo una fila puoi riscuotere tutto ciò che hai già raggiunto.",
