  "Tienes <b>5 equipos</b>: cambia entre ellos arriba. Elige <b>7 candidatos</b>. Empiezas solo con el <b>capitán</b>; al subir de nivel podrás fichar a los otros seis (máximo {MAX_TEAM} en el campo). Pulsa un futbolista de tu colección para añadirlo o quitarlo, pulsa una plaza para cambiarla, o arrastra para colocar e intercambiar. Se guarda solo.": "Hai <b>5 squadre</b>: passa dall'una all'altra in alto. Scegli <b>7 candidati</b>. Inizi solo con il <b>capitano</b>; salendo di livello potrai ingaggiare gli altri sei (massimo {MAX_TEAM} in campo). Tocca un giocatore della tua collezione per aggiungerlo o toglierlo, tocca un posto per cambiarlo, o trascina per piazzare e scambiare. Si salva da solo.",
