  "Elige el uniforme de tu escuadra: cambia el cuerpo y conserva la cabeza original y todas las animaciones. Se consiguen con las recompensas de equipo de la Enciclopedia.": "Scegli la divisa della tua squadra: cambia il corpo e mantiene la testa originale e tutte le animazioni. Si ottengono con le ricompense di squadra dell'Enciclopedia.",
