  "Devolver puntos": "Restituisci punti",
  "Cada ficha suma 1 punto a la estadística que elijas (máximo {tmax} para este futbolista). Se ganan con victorias, rangos superados, supervivencia infinita, misiones semanales y logros.": "Ogni gettone aggiunge 1 punto alla statistica che scegli (massimo {tmax} per questo giocatore). Si guadagnano con vittorie, ranghi superati, sopravvivenza infinita, missioni settimanali e obiettivi.",
