  "(efecto adaptado; sube con el nivel de la técnica)": "(effetto adattato; cresce con il livello della tecnica)",
  "Repertorio (2 técnicas activas en combate)": "Repertorio (2 tecniche attive in combattimento)",
  "☆ Empezar con esta": "☆ Inizia con questa",
  "✦ Ver su Aura": "✦ Vedi la sua Aura",
  "{add} Aura": "{add} Aura",
  "Valores centrados en 60: por encima suman, por debajo restan. Cada técnica usa las estadísticas de su futbolista. Lo propio llega a 99; con un Aura, hasta {EFFECTIVE_STAT_MAX}.": "Valori centrati su 60: sopra aggiungono, sotto tolgono. Ogni tecnica usa le statistiche del suo giocatore. Le statistiche proprie arrivano a 99; con un'Aura, fino a {EFFECTIVE_STAT_MAX}.",
