  "Ataque a los Titanes, Los Siete Pecados Capitales y Axel Encapuchado · {cost} fichas de evento la tirada": "L'attacco dei giganti, The Seven Deadly Sins e Axel Incappucciato · {cost} gettoni evento l'estrazione",
