  "NUEVO": "NUOVO",
  ": se desbloquea para siempre y ya puede ir en Mi Equipo.": ": sbloccato per sempre, ora può andare in La mia squadra.",
  "Duplicado": "Doppione",
  ": sirve para ascender al futbolista; si ya no puede ascender más, se convierte en monedas.": ": serve per far ascendere il giocatore; se non può più ascendere, si trasforma in monete.",
  "Los duplicados también pagan la <b>ascensión</b> de cualquier futbolista (Fix 1.53): cada ascensión sube una rareza y cuesta según la rareza desde la que sube (Común {ascenso}, Raro {ascenso2}, Épico {ascenso3}, Legendario {ascenso4}). Al llegar a Mítico, el HÉROE cuesta según la rareza con la que nació: Común {heroe}, Raro {heroe2}, Épico {heroe3}, Legendario {heroe4}, Mítico {heroe5} y Leyenda {heroe6}. Después, cada HÉROE gana hasta {HERO_STARS_MAX} estrellas de héroe (Mítico {estrella} duplicados cada una).": "I doppioni pagano anche l'<b>ascensione</b> di qualsiasi giocatore: ogni ascensione alza di una rarità e costa in base alla rarità di partenza (Comune {ascenso}, Raro {ascenso2}, Epico {ascenso3}, Leggendario {ascenso4}). Arrivati a Mitico, EROE costa in base alla rarità d'origine: Comune {heroe}, Raro {heroe2}, Epico {heroe3}, Leggendario {heroe4}, Mitico {heroe5} e Leggenda {heroe6}. Poi ogni EROE guadagna fino a {HERO_STARS_MAX} stelle eroe (Mitico {estrella} doppioni ciascuna).",
  "Con {MAX_STARS} estrellas y HÉROE, cada copia da monedas (de {comun} a {leyenda} según la rareza).": "Con {MAX_STARS} stelle ed EROE, ogni copia dà monete (da {comun} a {leyenda} in base alla rarità).",
  "Fichas = máquina de cápsulas · Monedas = mejoras y tiendas. Gráficos de la máquina: Inazuma Eleven 3 (hoja de The Spriters Resource, ripeada por Avegaille), recurso local.": "Gettoni = macchina delle capsule · Monete = potenziamenti e negozi. Grafica della macchina: Inazuma Eleven 3 (foglio di The Spriters Resource, estratto da Avegaille), risorsa locale.",
  "Duplicado · +{refund} monedas": "Doppione · +{refund} monete",
