  "Por comprar": "Da comprare",
  "REPERTORIO": "REPERTORIO",
  "Cada futbolista solo usa su propio repertorio. Aquí desbloqueas sus técnicas y compras <b>manuales</b> de daño permanente (subir de nivel una técnica en partida es aparte).": "Ogni giocatore usa solo il proprio repertorio. Qui sblocchi le sue tecniche e compri <b>manuali</b> di danno permanente (alzare di livello una tecnica in partita è un'altra cosa).",
  "Bonificaciones para todo el equipo. No cambian la equipación Raimon que se ve en combate.": "Bonus per tutta la squadra. Non cambiano la divisa Raimon che si vede in combattimento.",
  "InaZurvivors — Proyecto de fans no oficial": "InaZurvivors — Progetto di fan non ufficiale",
  "InaZurvivors es un fangame independiente y gratuito desarrollado por AstraStorm17, inspirado en la franquicia Inazuma Eleven.": "InaZurvivors è un fangame indipendente e gratuito sviluppato da AstraStorm17, ispirato alla saga di Inazuma Eleven.",
  "Inazuma Eleven, sus personajes, nombres, diseños, logotipos, música y materiales originales son propiedad de LEVEL-5 y/o sus respectivos titulares.": "Inazuma Eleven, i suoi personaggi, nomi, design, loghi, musiche e materiali originali sono proprietà di LEVEL-5 e/o dei rispettivi titolari.",
  "Este proyecto no está afiliado, patrocinado ni aprobado por LEVEL-5.": "Questo progetto non è affiliato, sponsorizzato né approvato da LEVEL-5.",
  "El código y los materiales originales desarrollados específicamente para InaZurvivors pertenecen a sus respectivos autores.": "Il codice e i materiali originali sviluppati appositamente per InaZurvivors appartengono ai rispettivi autori.",
  "Los recursos gráficos y sonoros de terceros conservan sus derechos originales.": "Le risorse grafiche e sonore di terzi mantengono i loro diritti originali.",
  "La inclusión de créditos y este aviso no implica la existencia de una licencia o autorización para distribuir material protegido.": "L'inclusione dei crediti e di questo avviso non implica l'esistenza di una licenza o autorizzazione a distribuire materiale protetto.",
  "Desarrollo": "Sviluppo",
  "Diseño, dirección y desarrollo: AstraStorm17.": "Ideazione, direzione e sviluppo: AstraStorm17.",
  "Programación con asistencia de Claude (Anthropic).": "Programmazione con l'assistenza di Claude (Anthropic).",
  "Recursos de terceros y su procedencia": "Risorse di terzi e loro provenienza",
  "Futbolistas, retratos, cuerpos, escudos, objetos, arenas y música: Inazuma Eleven 2 (LEVEL-5), extraídos de una copia propia del juego.": "Giocatori, ritratti, corpi, stemmi, oggetti, arene e musica: Inazuma Eleven 2 (LEVEL-5), estratti da una copia personale del gioco.",
  "Futbolistas, retratos y escudos de las sagas Mundial, GO, Chrono Stones, Galaxy, Ares y Orion: Inazuma Eleven 3 (LEVEL-5) con el parche de fans «Great Road of Heroes 3.1». Autoría del parche: no verificada; base y añadidos del parche no se pueden separar.": "Giocatori, ritratti e stemmi delle saghe Mondiale, GO, Chrono Stones, Galaxy, Ares e Orion: Inazuma Eleven 3 (LEVEL-5) con la patch dei fan «Great Road of Heroes 3.1». Autore della patch: non verificato; la base e le aggiunte della patch non si possono separare.",
  "Creados para InaZurvivors: efectos de supertécnicas, efectos de sonido, iconos de elemento, orbes, música «Generada» e interfaz.": "Creati per InaZurvivors: effetti delle supertecniche, effetti sonori, icone degli elementi, sfere, musica «Generata» e interfaccia.",
  "Redes sociales": "Social network",
  "Sobre el desarrollador": "Sullo sviluppatore",
  "AstraStorm también ha creado otros videojuegos.": "AstraStorm ha creato anche altri videogiochi.",
  "Enlaces oficiales": "Link ufficiali",
  "Sin cuenta, InaZurvivors no recopila datos personales: tu progreso se guarda solo en este navegador. Con cuenta online (Google) se guardan tu correo de Google (privado), tu nombre, tus marcas y tu guardado.": "Senza account, InaZurvivors non raccoglie dati personali: i tuoi progressi sono salvati solo in questo browser. Con un account online (Google) vengono salvati la tua email Google (privata), il tuo nome, i tuoi record e il tuo salvataggio.",
  "{VERSION_LABEL} · compilación interna {BUILD}": "{VERSION_LABEL} · build interna {BUILD}",
