  "Con la sesión iniciada, cada partida en solitario se graba (posiciones, técnicas y cartas, sin nada personal) para que el autor vea cómo se juega y equilibre el juego. Se guardan tus 3 últimas y las de tus marcas del ranking.": "Con l'accesso effettuato, ogni partita in solitario viene registrata (posizioni, tecniche e carte, niente di personale) perché l'autore veda come si gioca e bilanci il gioco. Si conservano le tue ultime 3 e quelle dei tuoi record in classifica.",
