  "{active}/{TRAIN_SLOTS} técnicas activas": "{active}/{TRAIN_SLOTS} tecniche attive",
  "Prueba las técnicas de tus futbolistas al nivel que quieras, también las combinadas que puedan hacer juntos (con sus Auras incluidas). Nadie recibe daño y no se gana nada: ni recompensas, ni misiones, ni ranking.": "Prova le tecniche dei tuoi giocatori al livello che vuoi, anche le combinate che possono fare insieme (Aure comprese). Nessuno subisce danni e non si guadagna niente: né ricompense, né missioni, né classifica.",
