  "Elige a quién echas del equipo. Pierdes sus técnicas y su parte de la vida, y su hueco queda libre para otro fichaje. El capitán no se puede echar.": "Scegli chi congedi dalla squadra. Perdi le sue tecniche e la sua parte di vita, e il suo posto resta libero per un altro ingaggio. Il capitano non può essere congedato.",
