  "Aguanta las oleadas de rivales hasta que llegue el jefe y derrótalo. Solo tu capitán recibe daño: si su vida llega a cero, pierdes (pero te quedas las monedas).": "Resisti alle ondate di avversari finché non arriva il boss e sconfiggilo. Solo il tuo capitano subisce danni: se la sua vita arriva a zero, perdi (ma tieni le monete).",
  "WASD o flechas (o el joystick táctil / mando). Las técnicas se lanzan solas: tú solo te colocas. ¡Pruébalo aquí!": "WASD o frecce (o il joystick touch / controller). Le tecniche partono da sole: tu devi solo posizionarti. Provalo qui!",
