  "Tiro, regate, defensa y parada atacan solos; los talentos son pasivos. Mejóralas hasta nivel 10 y evolucionan.": "Tiro, offesa, difesa e parata attaccano da soli; i talenti sono passivi. Migliorali fino al livello 10 ed evolvono.",
  "Teclas 1, 2 y 3. Ofensiva: más daño y más riesgo. Equilibrada: neutra. Defensiva: menos daño recibido. Toca una:": "Tasti 1, 2 e 3. Offensiva: più danni e più rischio. Equilibrata: neutra. Difensiva: meno danni subiti. Toccane una:",
  "Objetos y experiencia": "Oggetti ed esperienza",
  "Chispa verde, balón azul y rayo dorado dan experiencia (de menos a más). La comida cura y los objetos especiales te ayudan un rato.": "La scintilla verde, il pallone blu e il fulmine dorato danno esperienza (dal meno al più). Il cibo cura e gli oggetti speciali ti aiutano per un po'.",
