  "{x1}¿Cómo se calculan los puntos?": "{x1}Come si calcolano i punti?",
  "Puntos = (segundos × 10 + √daño × 2) × rango × arena. El rango es lo que más cuenta: C ×1, B ×1,6, A ×2,4, S ×3,4, X ×4,8 y Z ×7. La arena suma un 5% por cada etapa del camino, también las nuevas: {x1}.": "Punti = (secondi × 10 + √danni × 2) × rango × arena. Il rango è ciò che conta di più: C ×1, B ×1,6, A ×2,4, S ×3,4, X ×4,8 e Z ×7. L'arena aggiunge un 5% per ogni tappa del cammino, anche le nuove: {x1}.",
