  "Semana {x1}": "Settimana {x1}",
  "{x1}El bando es para toda la temporada y no se puede cambiar. Para que la lucha sea justa, el bando que vaya por delante en miembros no admite a nadie más hasta que el otro lo alcance. Cuentan las victorias de partidas normales (sin cooperativo, Road, clan ni entrenamiento).": "{x1}La fazione è per tutta la stagione e non si può cambiare. Perché la lotta sia giusta, la fazione in vantaggio di membri non accetta nessun altro finché l'altra non la raggiunge. Contano le vittorie delle partite normali (niente cooperativa, Road, clan né allenamento).",
  "Road to Fútbol Frontier: ahora Jaden sale a las 3 victorias en Máxima y otra copia cada 3. Por tus victorias recibes {x1}.": "Road to Football Frontier: ora Jaden arriva a 3 vittorie in Massima e un'altra copia ogni 3. Per le tue vittorie ricevi {x1}.",
