  "Sin vínculo especial con {pName}. Un compañero de historia, familia o técnica conjunta daría {x1}%.": "Nessun legame speciale con {pName}. Un compagno di storia, di famiglia o di tecnica congiunta darebbe il {x1}%.",
  "Bonificación = estadística del Aura × {x1}%, redondeada. Lo propio sigue en 99 como máximo; con el Aura, hasta {EFFECTIVE_STAT_MAX}.": "Bonus = statistica dell'Aura × {x1}%, arrotondato. Le statistiche proprie restano al massimo a 99; con l'Aura, fino a {EFFECTIVE_STAT_MAX}.",
  "{x1} · {x2} · poder {power}": "{x1} · {x2} · potenza {power}",
  "La primera empieza la partida en una ranura extra de Aura; la segunda puede aprenderse al subir de nivel. Golpean al {x1}% (son una técnica activa de más). No sustituyen a las suyas y desaparecen si quitas el Aura.": "La prima inizia la partita in uno slot Aura extra; la seconda si può imparare salendo di livello. Colpiscono al {x1}% (sono una tecnica attiva in più). Non sostituiscono le sue e spariscono se togli l'Aura.",
  "{x1} Afinidad de {x2}": "{x1} Affinità {x2}",
  "Las técnicas de {pName} de elemento {x1} (también las heredadas) hacen <b>+{x2}%</b> de daño. {pName} sigue siendo de {x3} para todo lo demás.": "Le tecniche {x1} di {pName} (anche quelle ereditate) fanno <b>+{x2}%</b> di danni. {pName} resta {x3} per tutto il resto.",
