  "EVENTO · TERMINA EN {x1}": "EVENTO · TERMINA TRA {x1}",
  "{x1} ◉ la tirada · Míticos al 3%": "{x1} ◉ l'estrazione · Mitici al 3%",
  "DÍA {x1}{x2}": "GIORNO {x1}{x2}",
  "{x1} Si te saltas días no pierdes nada: el pase te espera.": "{x1} Se salti dei giorni non perdi nulla: il pass ti aspetta.",
  "{x1}{x2} · tras el día {PASSLength} empieza un ciclo nuevo": "{x1}{x2} · dopo il giorno {PASSLength} inizia un nuovo ciclo",
  "{x1} <b>{x2}</b>, y si llevas {min} o más jugadores de ese equipo en el campo, «Química de club»: +{x3}% de daño.": "{x1} <b>{x2}</b>, e se hai {min} o più giocatori di quella squadra in campo, «Intesa di club»: +{x3}% di danni.",
  "Posiciones distintas ({x1} / {x2}): la comparación es orientativa.": "Ruoli diversi ({x1} / {x2}): il confronto è indicativo.",
