  "Faltan duplicados: {x1} más": "Doppioni mancanti: altri {x1}",
  "Faltan {x1} monedas": "Mancano {x1} monete",
  "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · daño ×{toFixed} · vida ×{toFixed2} · duplicados libres {sparesOf}": "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · danni ×{toFixed} · vita ×{toFixed2} · doppioni liberi {sparesOf}",
  "✦ Elige {x1} de límite (+{STAR_CAP_STEP})": "✦ Scegli {x1} di limite (+{STAR_CAP_STEP})",
  "Toca una estadística por cada estrella: su límite sube +{STAR_CAP_STEP}. Puedes repetir la misma.{x1}": "Tocca una statistica per ogni stella: il suo limite sale di +{STAR_CAP_STEP}. Puoi ripetere la stessa.{x1}",
  "{pName}: {done} {x1} de límite": "{pName}: {done} {x1} di limite",
  "★ Estrella de héroe ({sparesOf}/{x1})": "★ Stella eroe ({sparesOf}/{x1})",
  "▲ Ascensión ({sparesOf}/{x1})": "▲ Ascensione ({sparesOf}/{x1})",
  "Maestría {x1}/{MASTERY_USESLength} · +{x2}% daño · {x3} usos": "Maestria {x1}/{MASTERY_USESLength} · +{x2}% di danni · {x3} usi",
  "Estadísticas · media {statMean}{x1}": "Statistiche · media {statMean}{x1}",
  "(con su Aura {aeName}; propia {x1})": "(con la sua Aura {aeName}; propria {x1})",
  "COLABORACIÓN · TERMINA EN {x1}": "COLLABORAZIONE · TERMINA TRA {x1}",
  "★ Destacada hoy: Épico ×{x1} · Legendario, Mítico y Leyenda ×{x2}": "★ In evidenza oggi: Epico ×{x1} · Leggendario, Mitico e Leggenda ×{x2}",
  "{x1}Precio y reglas": "{x1}Prezzo e regole",
  "Los futbolistas especiales solo salen aquí, con {x1} Comunes, Raros y Épicos de relleno. Se paga con fichas de evento: cada partida en Rango S o X te da tantas como fichas normales mientras dura el evento.": "I giocatori speciali escono solo qui, con {x1} Comuni, Rari ed Epici di riempimento. Si paga con gettoni evento: ogni partita in Rango S o X te ne dà quanti gettoni normali finché dura l'evento.",
  "{x1}Tus {unit}": "{x1}I tuoi {unit}",
  "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (diez ×10 de golpe, un Épico o mejor asegurado en cada diez). {x4}{x5}": "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (dieci ×10 in un colpo, un Epico o meglio garantito ogni dieci). {x4}{x5}",
  "Te llega para {x1} tirada(s).": "Ti basta per {x1} estrazione/i.",
  "{x1}Cómo conseguir fichas": "{x1}Come ottenere gettoni",
  "{x1}Nuevo, duplicado y ascensión": "{x1}Nuovo, doppione e ascensione",
  "(hasta {MAX_STARS}): se compran con monedas en su ficha (10.000, 20.000… 50.000). Cada una da +{x1}% daño, +{x2}% vida y +5 al límite de la estadística que elijas. Los HÉROES y Campeones tienen 3 estrellas extra (100.000, 110.000 y 120.000).": "(fino a {MAX_STARS}): si comprano con monete nella sua scheda (10.000, 20.000… 50.000). Ognuna dà +{x1}% di danni, +{x2}% di vita e +5 al limite della statistica che scegli. Gli EROI e i Campioni hanno 3 stelle extra (100.000, 110.000 e 120.000).",
  "{x1}Probabilidades": "{x1}Probabilità",
  "{x1}: sin futbolistas por ahora; su probabilidad pasa a la rareza inferior.": "{x1}: nessun giocatore per ora; la sua probabilità passa alla rarità inferiore.",
