  "{x1}Tu plantilla": "{x1}La tua rosa",
  "{x1} · {techniquesLength} técnicas": "{x1} · {techniquesLength} tecniche",
  "Máquina de cápsulas: gráficos de Inazuma Eleven 3 (LEVEL-5), hoja publicada en {x1}, ripeada por Avegaille.": "Macchina delle capsule: grafica di Inazuma Eleven 3 (LEVEL-5), foglio pubblicato su {x1}, estratto da Avegaille.",
  "Nombres en español e inglés de parte de las técnicas: {x1} (Fandom), contenido bajo {x2}.": "Nomi spagnoli e inglesi di parte delle tecniche: {x1} (Fandom), contenuto sotto {x2}.",
  "Motor: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Herramienta: {x3} (MIT).": "Motore: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Strumento: {x3} (MIT).",
  "Fuente: Press Start 2P © The Press Start 2P Project Authors ({x1}), vía Fontsource.": "Font: Press Start 2P © The Press Start 2P Project Authors ({x1}), tramite Fontsource.",
  "Ahora suena: {x1}. Por defecto suena la música de Inazuma Eleven exportada de tu copia. «Generada» usa temas creados para este proyecto.": "In riproduzione: {x1}. Di default suona la musica di Inazuma Eleven esportata dalla tua copia. «Generata» usa brani creati per questo progetto.",
  "Vuelves a empezar como un jugador nuevo{x1}. No es lo mismo que eliminar la cuenta.": "Ricominci come un nuovo giocatore{x1}. Non è come eliminare l'account.",
