  "Esperando a que <b>{partner}</b> elija la arena y empiece…": "In attesa che <b>{partner}</b> scelga l'arena e inizi…",
  "Mis depósitos": "I miei depositi",
  ": otro dispositivo guardó una versión más nueva": ": un altro dispositivo ha salvato una versione più recente",
  "Próximo gran premio: <b>{label}</b> · nivel {x1} {x2} · faltan {x3}": "Prossimo grande premio: <b>{label}</b> · livello {x1} {x2} · mancano {x3}",
  "Ver el Sector": "Vedi il Settore",
  "El fútbol necesita orden. A partir de hoy, el Sector Quinto decide cómo se juega cada partido.": "Il calcio ha bisogno di ordine. Da oggi, il Quinto Settore decide come si gioca ogni incontro.",
  "Únete a nosotros… o intenta resistir. Cada semana veremos qué bando juega mejor.": "Unisciti a noi… o prova a resistere. Ogni settimana vedremo quale fazione gioca meglio.",
  "Bienvenido al Sector Quinto. Aquí el fútbol se juega como yo digo.": "Benvenuto nel Quinto Settore. Qui il calcio si gioca come dico io.",
  "Acata mis decretos y tu bando ganará.": "Obbedisci ai miei decreti e la tua fazione vincerà.",
  "La Resistencia… Veremos cuánto aguanta vuestro viento.": "La Resistenza… Vedremo quanto dura il vostro vento.",
  "Rebélate si quieres: el Sector Quinto también sabe jugar duro.": "Ribellati, se vuoi: anche il Quinto Settore sa giocare duro.",
  "¡Llega {eName}!": "Arriva {eName}!",
  "{x1} · {x2} rivales · Nv {level}": "{x1} · {x2} avversari · Lv {level}",
  "sus estadísticas (Aura legendaria)": "le sue statistiche (Aura leggendaria)",
  "Cada plaza de tu equipo tiene ahora una <b>{x1}</b> {x2} <b>{x3}</b>. Ahí pones a otro futbolista de tu colección para que apoye al de la plaza. El Aura no juega: lo potencia.": "Ogni posto della tua squadra ha ora una <b>{x1}</b> {x2} <b>{x3}</b>. Lì metti un altro giocatore della tua collezione perché sostenga quello del posto. L'Aura non gioca: lo potenzia.",
  "Solo pueden ser Aura los <b>Legendarios, Míticos y Leyendas</b>.": "Possono essere Aura solo i <b>Leggendari, Mitici e Leggende</b>.",
  "Una por futbolista. No se gasta nada: tu colección no cambia.": "Una per giocatore. Non si spende nulla: la tua collezione non cambia.",
  "El Aura suma el <b>{x1}%</b> {x2} <b>{x3}</b> a las mismas del portador.": "L'Aura aggiunge il <b>{x1}%</b> {x2} <b>{x3}</b> alle stesse del portatore.",
  "Ejemplo: Tiro 90 + Aura con Tiro 95 » 90 + 14 = <b>104</b>.": "Esempio: Tiro 90 + Aura con Tiro 95 » 90 + 14 = <b>104</b>.",
  "Lo propio sigue en 99 como máximo; con el Aura, hasta <b>120</b>, y en el combate se nota.": "Le statistiche proprie restano al massimo a 99; con l'Aura, fino a <b>120</b>, e in combattimento si nota.",
  "En el radar, lo que aporta el Aura se ve en <b style=\"color:#7ff6ff\">cian</b>.": "Sul radar, ciò che dà l'Aura si vede in <b style=\"color:#7ff6ff\">ciano</b>.",
  "Si los dos tienen historia (técnica conjunta, amistad, familia o rivalidad), el Aura da el <b>{x1}%</b>{x2} <b>♥</b>.": "Se i due hanno una storia (tecnica congiunta, amicizia, famiglia o rivalità), l'Aura dà il <b>{x1}%</b>{x2} <b>♥</b>.",
  "Axel y Shawn, Mark y Nathan, Jude y Celia, Arion y Riccardo...": "Axel e Shawn, Mark e Nathan, Jude e Celia, Arion e Riccardo...",
  "Estar en el mismo equipo no basta.": "Stare nella stessa squadra non basta.",
  "El portador hereda <b>{x1}</b> del Aura: una empieza la partida en una ranura extra y la otra llega como carta al subir de nivel. No sustituyen a las suyas.": "Il portatore eredita <b>{x1}</b> dall'Aura: una inizia la partita in uno slot extra e l'altra arriva come carta salendo di livello. Non sostituiscono le sue.",
  "Sus técnicas del elemento del Aura hacen <b>+{x1}%</b>.": "Le sue tecniche dell'elemento dell'Aura fanno <b>+{x1}%</b>.",
  "Con el Aura puede lanzar <b>{x1}</b>: Axel con Shawn de Aura, Fuego cruzado.": "Con l'Aura può lanciare <b>{x1}</b>: Axel con Shawn come Aura, Fuoco Incrociato.",
  "Cómo equiparla:": "Come equipaggiarla:",
  "toca «+ AURA» y elige en tu colección, o arrastra la carta encima.": "tocca «+ AURA» e scegli nella tua collezione, o trascina la carta sopra.",
  "Elige quién va a la <b>{x1}</b> ·": "Scegli chi va nella <b>{x1}</b> ·",
