  "Resto con marca": "Tutti gli altri con un record",
  "El fútbol bajo control: cada partido, como el Sector decide.": "Il calcio sotto controllo: ogni incontro, come decide il Settore.",
  "El fútbol es libre: el viento de la revolución sopla en cada partido.": "Il calcio è libero: il vento della rivoluzione soffia in ogni incontro.",
  "El viento sopla a favor del Sector. Esta semana, quien domine el Aire dominará el campo.": "Il vento soffia a favore del Settore. Questa settimana, chi domina il Vento dominerà il campo.",
  "El Sector quiere goles de fuego. Esta semana, las técnicas de Fuego arden con más fuerza.": "Il Settore vuole gol di fuoco. Questa settimana, le tecniche Fuoco bruciano più forte.",
  "Raíces firmes, disciplina firme. Esta semana el Bosque crece bajo la mirada del Sector.": "Radici salde, disciplina salda. Questa settimana la Foresta cresce sotto lo sguardo del Settore.",
  "Nadie mueve una montaña sin permiso. Esta semana la Montaña es la ley.": "Nessuno sposta una montagna senza permesso. Questa settimana la Montagna è legge.",
  "Técnicas de {e} −40 %": "Tecniche {e} −40%",
  "En este partido el {e} no está autorizado. Juega como el Sector dice.": "In questo incontro l'elemento {e} non è autorizzato. Gioca come dice il Settore.",
  "Recibes +25 % de daño": "Subisci +25% di danni",
  "Tu defensa no interesa al Sector. Aguanta los golpes en silencio.": "La tua difesa non interessa al Settore. Incassa i colpi in silenzio.",
  "Todas las técnicas −15 %": "Tutte le tecniche −15%",
  "Nada de lucirse: un partido gris, sin estrellas. Así lo quiere el Sector.": "Niente esibizioni: un incontro grigio, senza stelle. Così lo vuole il Settore.",
