  "Grabas, editas y subes: InaZurvivors llega más lejos gracias a ti.": "Registri, monti e pubblichi: InaZurvivors arriva più lontano grazie a te.",
  "Marco de Creador": "Cornice del Creatore",
  "Un botón de play con alas: el marco de quien graba InaZurvivors.": "Un pulsante play con le ali: la cornice di chi registra InaZurvivors.",
  "Tu última partida se cortó a los {x1}: aquí tienes lo que llevabas ganado.": "La tua ultima partita si è interrotta a {x1}: ecco quello che avevi guadagnato.",
